using System.Security.Cryptography;
using Microsoft.EntityFrameworkCore;
var builder=WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<Db>(o=>o.UseSqlite(builder.Configuration.GetConnectionString("CampusBite")));builder.Services.AddHttpClient();
builder.Services.AddCors(o=>o.AddDefaultPolicy(p=>p.WithOrigins("http://localhost:5500","http://127.0.0.1:5500","http://localhost:5501","http://127.0.0.1:5501").AllowAnyHeader().AllowAnyMethod()));
var app=builder.Build();app.UseCors();
using(var s=app.Services.CreateScope()){var db=s.ServiceProvider.GetRequiredService<Db>();db.Database.EnsureCreated();if(!db.Categories.Any()){db.Categories.AddRange(new Cat{Name="Meals"},new Cat{Name="Snacks"},new Cat{Name="Drinks"},new Cat{Name="Desserts"});db.SaveChanges();}if(!db.Users.Any(x=>x.Email=="admin@campusbite.com")){db.Users.Add(new User{FullName="CampusBite Administrator",Email="admin@campusbite.com",PasswordHash=Hash("Admin123!"),Role="Admin",CreatedAt=DateTime.UtcNow});db.SaveChanges();}if(!db.Users.Any(x=>x.Email=="student@campusbite.com")){var demoStudentId=db.Users.Any(x=>x.StudentId=="2026-1001")?"CB-DEMO-"+DateTime.UtcNow.ToString("yyyyMMddHHmmss"):"2026-1001";db.Users.Add(new User{FullName="Demo Student",StudentId=demoStudentId,Email="student@campusbite.com",PasswordHash=Hash("Student123!"),Role="Student",CreatedAt=DateTime.UtcNow});db.SaveChanges();}if(!db.Products.Any()){var c=db.Categories.ToDictionary(x=>x.Name,x=>x.Id);db.Products.AddRange(new Product{Name="Chicken Rice Meal",CategoryId=c["Meals"],Price=75,StockQuantity=40,Emoji="🍗"},new Product{Name="Spaghetti",CategoryId=c["Meals"],Price=65,StockQuantity=30,Emoji="🍝"},new Product{Name="Burger",CategoryId=c["Snacks"],Price=50,StockQuantity=35,Emoji="🍔"},new Product{Name="Hotdog Sandwich",CategoryId=c["Snacks"],Price=45,StockQuantity=25,Emoji="🌭"},new Product{Name="French Fries",CategoryId=c["Snacks"],Price=40,StockQuantity=50,Emoji="🍟"},new Product{Name="Caramel Pudding",CategoryId=c["Desserts"],Price=40,StockQuantity=20,Emoji="🍮"},new Product{Name="Iced Tea",CategoryId=c["Drinks"],Price=25,StockQuantity=60,Emoji="🧋"});db.SaveChanges();}}
app.MapGet("/",()=>Results.Ok(new{application="CampusBite API",status="running"}));app.MapGet("/api/health",()=>Results.Ok(new{status="ok"}));
app.MapPost("/api/auth/register",async(Reg r,Db d)=>{if(string.IsNullOrWhiteSpace(r.FullName)||string.IsNullOrWhiteSpace(r.StudentId)||string.IsNullOrWhiteSpace(r.Email)||string.IsNullOrWhiteSpace(r.Password))return Results.BadRequest(new{message="All fields are required."});if(r.Password.Length<8)return Results.BadRequest(new{message="Password must be at least 8 characters."});var e=r.Email.Trim().ToLower();if(await d.Users.AnyAsync(x=>x.Email==e))return Results.Conflict(new{message="Email already registered."});if(await d.Users.AnyAsync(x=>x.StudentId==r.StudentId.Trim()))return Results.Conflict(new{message="Student ID already registered."});var u=new User{FullName=r.FullName.Trim(),StudentId=r.StudentId.Trim(),Email=e,PasswordHash=Hash(r.Password),Role="Student",CreatedAt=DateTime.UtcNow};d.Users.Add(u);await d.SaveChangesAsync();return Results.Created("/api/users/me",Pub(u));});
app.MapPost("/api/auth/login",async(Login r,Db d)=>{var u=await d.Users.FirstOrDefaultAsync(x=>x.Email==((r.Email??"").Trim().ToLower()));if(u==null||!Verify(r.Password??"",u.PasswordHash))return Results.Json(new{message="Invalid email or password."},statusCode:401);var t=Convert.ToBase64String(RandomNumberGenerator.GetBytes(32));Tokens.Values[t]=u.Id;return Results.Ok(new{token=t,user=Pub(u)});});
app.MapGet("/api/products",async(Db d)=>Results.Ok((await d.Products.Include(x=>x.Category).OrderBy(x=>x.Name).ToListAsync()).Select(x=>PD(x)).ToList()));
app.MapGet("/api/products/{id:int}",async(int id,Db d)=>{var p=await d.Products.Include(x=>x.Category).FirstOrDefaultAsync(x=>x.Id==id);return p==null?Results.NotFound(new{message="Food item not found."}):Results.Ok(PD(p));});
app.MapPost("/api/products",async(Prod r,Db d,HttpContext c)=>{if(!Admin(c,d))return Results.Json(new{message="Admin access required."},statusCode:403);if(string.IsNullOrWhiteSpace(r.Name)||r.Price<=0||r.StockQuantity<0)return Results.BadRequest(new{message="Enter a name, positive price, and non-negative stock."});if(!await d.Categories.AnyAsync(x=>x.Id==r.CategoryId))return Results.BadRequest(new{message="Choose a valid category."});var p=new Product{Name=r.Name.Trim(),CategoryId=r.CategoryId,Price=r.Price,StockQuantity=r.StockQuantity,Emoji=r.Emoji??"🍱",IsActive=r.IsActive};d.Products.Add(p);await d.SaveChangesAsync();await d.Entry(p).Reference(x=>x.Category).LoadAsync();return Results.Created($"/api/products/{p.Id}",PD(p));});
app.MapPut("/api/products/{id:int}",async(int id,Prod r,Db d,HttpContext c)=>{if(!Admin(c,d))return Results.Json(new{message="Admin access required."},statusCode:403);var p=await d.Products.FindAsync(id);if(p==null)return Results.NotFound(new{message="Food item not found."});if(string.IsNullOrWhiteSpace(r.Name)||r.Price<=0||r.StockQuantity<0||!await d.Categories.AnyAsync(x=>x.Id==r.CategoryId))return Results.BadRequest(new{message="Check the food name, category, price, and stock."});p.Name=r.Name.Trim();p.CategoryId=r.CategoryId;p.Price=r.Price;p.StockQuantity=r.StockQuantity;p.Emoji=r.Emoji??"🍱";p.IsActive=r.IsActive;await d.SaveChangesAsync();await d.Entry(p).Reference(x=>x.Category).LoadAsync();return Results.Ok(PD(p));});
app.MapDelete("/api/products/{id:int}",async(int id,Db d,HttpContext c)=>{if(!Admin(c,d))return Results.Json(new{message="Admin access required."},statusCode:403);var p=await d.Products.FindAsync(id);if(p==null)return Results.NotFound();if(await d.Items.AnyAsync(x=>x.ProductId==id))return Results.Conflict(new{message="This item is in order history. Mark it inactive instead."});d.Products.Remove(p);await d.SaveChangesAsync();return Results.NoContent();});
app.MapGet("/api/categories",async(Db d)=>Results.Ok(await d.Categories.OrderBy(x=>x.Name).Select(x=>new{ x.Id,name=x.Name,productCount=x.Products.Count}).ToListAsync()));
app.MapPost("/api/categories",async(CatReq r,Db d,HttpContext c)=>{if(!Admin(c,d))return Results.Json(new{message="Admin access required."},statusCode:403);var n=(r.Name??"").Trim();if(n=="")return Results.BadRequest(new{message="Category name required."});if(await d.Categories.AnyAsync(x=>x.Name.ToLower()==n.ToLower()))return Results.Conflict(new{message="Category already exists."});var x=new Cat{Name=n};d.Categories.Add(x);await d.SaveChangesAsync();return Results.Created($"/api/categories/{x.Id}",new{x.Id,name=x.Name,productCount=0});});
app.MapDelete("/api/categories/{id:int}",async(int id,Db d,HttpContext c)=>{if(!Admin(c,d))return Results.Json(new{message="Admin access required."},statusCode:403);var x=await d.Categories.Include(x=>x.Products).FirstOrDefaultAsync(x=>x.Id==id);if(x==null)return Results.NotFound();if(x.Products.Count>0)return Results.Conflict(new{message="Category still has food items."});d.Categories.Remove(x);await d.SaveChangesAsync();return Results.NoContent();});
app.MapPost("/api/orders",async(NewOrder r,Db d,HttpContext c)=>{var u=await Current(c,d);if(u==null)return Results.Json(new{message="Please sign in again."},statusCode:401);if(r.Items==null||r.Items.Count==0)return Results.BadRequest(new{message="Cart is empty."});await using var tx=await d.Database.BeginTransactionAsync();var o=new Order{OrderNumber="CB-"+DateTime.UtcNow.ToString("yyyyMMddHHmmss")+"-"+Random.Shared.Next(10,99),UserId=u.Id,CreatedAt=DateTime.UtcNow,Status="Pending",PickupOption=r.PickupOption,PaymentMethod=r.PaymentMethod,Notes=r.Notes??""};foreach(var i in r.Items){if(i.Quantity<1)return Results.BadRequest(new{message="Quantity must be positive."});var p=await d.Products.FirstOrDefaultAsync(x=>x.Id==i.ProductId&&x.IsActive);if(p==null)return Results.BadRequest(new{message="A food item is unavailable."});if(p.StockQuantity<i.Quantity)return Results.BadRequest(new{message=$"Not enough stock for {p.Name}."});p.StockQuantity-=i.Quantity;o.Items.Add(new Item{ProductId=p.Id,ProductName=p.Name,Quantity=i.Quantity,UnitPrice=p.Price});o.TotalAmount+=p.Price*i.Quantity;}d.Orders.Add(o);await d.SaveChangesAsync();await tx.CommitAsync();return Results.Created($"/api/orders/{o.Id}",OD(o,u.FullName));});
app.MapGet("/api/orders/mine",async(Db d,HttpContext c)=>{var u=await Current(c,d);if(u==null)return Results.Json(new{message="Please sign in again."},statusCode:401);var os=await d.Orders.Include(x=>x.Items).Where(x=>x.UserId==u.Id).OrderByDescending(x=>x.CreatedAt).ToListAsync();return Results.Ok(os.Select(x=>OD(x,u.FullName)));});
app.MapGet("/api/orders/{id:int}",async(int id,Db d,HttpContext c)=>{var u=await Current(c,d);if(u==null)return Results.Json(new{message="Please sign in again."},statusCode:401);var o=await d.Orders.Include(x=>x.Items).FirstOrDefaultAsync(x=>x.Id==id);if(o==null)return Results.NotFound(new{message="Order not found."});if(u.Role!="Admin"&&o.UserId!=u.Id)return Results.Json(new{message="Not allowed."},statusCode:403);return Results.Ok(OD(o,(await d.Users.FindAsync(o.UserId))?.FullName??""));});
app.MapGet("/api/admin/orders",async(Db d,HttpContext c)=>{if(!Admin(c,d))return Results.Json(new{message="Admin access required."},statusCode:403);var os=await d.Orders.Include(x=>x.Items).Include(x=>x.User).OrderByDescending(x=>x.CreatedAt).ToListAsync();return Results.Ok(os.Select(x=>OD(x,x.User!.FullName)));});
app.MapPut("/api/admin/orders/{id:int}/status",async(int id,StatusUpdate r,Db d,HttpContext c)=>{if(!Admin(c,d))return Results.Json(new{message="Admin access required."},statusCode:403);if(!new[]{"Pending","Preparing","Ready","Completed","Cancelled"}.Contains(r.Status))return Results.BadRequest(new{message="Invalid status."});var o=await d.Orders.FindAsync(id);if(o==null)return Results.NotFound();if(o.Status!="Cancelled"&&r.Status=="Cancelled"){foreach(var i in await d.Items.Where(x=>x.OrderId==id).ToListAsync()){var p=await d.Products.FindAsync(i.ProductId);if(p!=null)p.StockQuantity+=i.Quantity;}}o.Status=r.Status;await d.SaveChangesAsync();return Results.Ok(new{id,status=o.Status});});
app.MapGet("/api/admin/summary",async(Db d,HttpContext c)=>{if(!Admin(c,d))return Results.Json(new{message="Admin access required."},statusCode:403);var os=await d.Orders.Include(x=>x.User).OrderByDescending(x=>x.CreatedAt).Take(8).ToListAsync();return Results.Ok(new{totalOrders=await d.Orders.CountAsync(),pendingOrders=await d.Orders.CountAsync(x=>x.Status=="Pending"),totalProducts=await d.Products.CountAsync(),totalUsers=await d.Users.CountAsync(),recentOrders=os.Select(x=>new{x.Id,x.OrderNumber,x.CreatedAt,x.Status,x.TotalAmount,customerName=x.User!.FullName})});});
app.MapGet("/api/admin/reports",async(Db d,HttpContext c)=>{if(!Admin(c,d))return Results.Json(new{message="Admin access required."},statusCode:403);var os=await d.Orders.Include(x=>x.User).OrderByDescending(x=>x.CreatedAt).Take(100).ToListAsync();return Results.Ok(new{totalOrders=await d.Orders.CountAsync(),totalSales=await d.Orders.Where(x=>x.Status!="Cancelled").SumAsync(x=>(decimal?)x.TotalAmount)??0,totalUsers=await d.Users.CountAsync(),totalProducts=await d.Products.CountAsync(),recentOrders=os.Select(x=>new{x.Id,x.OrderNumber,x.CreatedAt,x.Status,x.TotalAmount,customerName=x.User!.FullName})});});
app.MapGet("/api/admin/users",async(Db d,HttpContext c)=>!Admin(c,d)?Results.Json(new{message="Admin access required."},statusCode:403):Results.Ok(await d.Users.OrderByDescending(x=>x.CreatedAt).Select(x=>new{x.Id,x.FullName,x.StudentId,x.Email,x.Role,x.CreatedAt}).ToListAsync()));
app.MapPut("/api/users/me",async(Profile r,Db d,HttpContext c)=>{var u=await Current(c,d);if(u==null)return Results.Json(new{message="Please sign in again."},statusCode:401);if(string.IsNullOrWhiteSpace(r.FullName))return Results.BadRequest(new{message="Name is required."});u.FullName=r.FullName.Trim();u.Phone=r.Phone??"";await d.SaveChangesAsync();return Results.Ok(Pub(u));});
app.MapGet("/api/weather",async(IHttpClientFactory factory)=>{try{using var response=await factory.CreateClient().GetAsync("https://api.open-meteo.com/v1/forecast?latitude=7.1907&longitude=124.5307&current=temperature_2m,relative_humidity_2m,weather_code");response.EnsureSuccessStatusCode();using var doc=System.Text.Json.JsonDocument.Parse(await response.Content.ReadAsStringAsync());var cur=doc.RootElement.GetProperty("current");var code=cur.GetProperty("weather_code").GetInt32();var condition=code==0?"Clear":code<=3?"Partly cloudy":code<=48?"Foggy":code<=67?"Rain":code<=77?"Snow":code<=82?"Rain showers":code<=86?"Snow showers":"Thunderstorm";return Results.Ok(new{location="Midsayap / Campus Area",temperatureC=cur.GetProperty("temperature_2m").GetDecimal(),condition,humidity=cur.GetProperty("relative_humidity_2m").GetInt32(),source="Open-Meteo"});}catch{return Results.Ok(new{location="Campus",temperatureC=29,condition="Unavailable (sample fallback)",humidity=78,source="Fallback"});}});app.Run();
static string Hash(string p){var s=RandomNumberGenerator.GetBytes(16);return Convert.ToBase64String(s)+"."+Convert.ToBase64String(Rfc2898DeriveBytes.Pbkdf2(p,s,120000,HashAlgorithmName.SHA256,32));}
static bool Verify(string p,string h){try{var a=h.Split('.');return CryptographicOperations.FixedTimeEquals(Convert.FromBase64String(a[1]),Rfc2898DeriveBytes.Pbkdf2(p,Convert.FromBase64String(a[0]),120000,HashAlgorithmName.SHA256,32));}catch{return false;}}
static object Pub(User u)=>new{id=u.Id,fullName=u.FullName,studentId=u.StudentId,email=u.Email,role=u.Role,phone=u.Phone,createdAt=u.CreatedAt};
static object PD(Product p)=>new{id=p.Id,name=p.Name,categoryId=p.CategoryId,categoryName=p.Category?.Name,price=p.Price,stockQuantity=p.StockQuantity,emoji=p.Emoji,isActive=p.IsActive};
static object OD(Order o,string name)=>new{id=o.Id,orderNumber=o.OrderNumber,createdAt=o.CreatedAt,status=o.Status,pickupOption=o.PickupOption,paymentMethod=o.PaymentMethod,notes=o.Notes,totalAmount=o.TotalAmount,customerName=name,items=o.Items.Select(i=>new{id=i.Id,productId=i.ProductId,productName=i.ProductName,quantity=i.Quantity,unitPrice=i.UnitPrice})};
static async Task<User?> Current(HttpContext c,Db d){var h=c.Request.Headers.Authorization.ToString();if(!h.StartsWith("Bearer ")||!Tokens.Values.TryGetValue(h[7..],out var id))return null;return await d.Users.FindAsync(id);}
static bool Admin(HttpContext c,Db d){var h=c.Request.Headers.Authorization.ToString();return h.StartsWith("Bearer ")&&Tokens.Values.TryGetValue(h[7..],out var id)&&d.Users.Any(x=>x.Id==id&&x.Role=="Admin");}
static class Tokens{public static Dictionary<string,int> Values=new();}
class Db(DbContextOptions<Db> o):DbContext(o){public DbSet<User> Users=>Set<User>();public DbSet<Cat> Categories=>Set<Cat>();public DbSet<Product> Products=>Set<Product>();public DbSet<Order> Orders=>Set<Order>();public DbSet<Item> Items=>Set<Item>();protected override void OnModelCreating(ModelBuilder b){b.Entity<User>().HasIndex(x=>x.Email).IsUnique();b.Entity<User>().HasIndex(x=>x.StudentId).IsUnique();b.Entity<Cat>().HasIndex(x=>x.Name).IsUnique();b.Entity<Product>().Property(x=>x.Price).HasPrecision(10,2);b.Entity<Product>().HasOne(x=>x.Category).WithMany(x=>x.Products).HasForeignKey(x=>x.CategoryId).OnDelete(DeleteBehavior.Restrict);b.Entity<Order>().Property(x=>x.TotalAmount).HasPrecision(10,2);b.Entity<Order>().HasOne(x=>x.User).WithMany(x=>x.Orders).HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Restrict);b.Entity<Item>().Property(x=>x.UnitPrice).HasPrecision(10,2);b.Entity<Item>().HasOne(x=>x.Order).WithMany(x=>x.Items).HasForeignKey(x=>x.OrderId);b.Entity<Item>().HasOne(x=>x.Product).WithMany(x=>x.Items).HasForeignKey(x=>x.ProductId).OnDelete(DeleteBehavior.Restrict);}}
class User{public int Id{get;set;}public string FullName{get;set;}="";public string? StudentId{get;set;}public string Email{get;set;}="";public string PasswordHash{get;set;}="";public string Role{get;set;}="Student";public string? Phone{get;set;}public DateTime CreatedAt{get;set;}public List<Order> Orders{get;set;}=[];}
class Cat{public int Id{get;set;}public string Name{get;set;}="";public List<Product> Products{get;set;}=[];}
class Product{public int Id{get;set;}public string Name{get;set;}="";public int CategoryId{get;set;}public Cat? Category{get;set;}public decimal Price{get;set;}public int StockQuantity{get;set;}public string Emoji{get;set;}="🍱";public bool IsActive{get;set;}=true;public List<Item> Items{get;set;}=[];}
class Order{public int Id{get;set;}public string OrderNumber{get;set;}="";public int UserId{get;set;}public User? User{get;set;}public DateTime CreatedAt{get;set;}public string Status{get;set;}="Pending";public string PickupOption{get;set;}="Main Canteen";public string PaymentMethod{get;set;}="Cash";public string Notes{get;set;}="";public decimal TotalAmount{get;set;}public List<Item> Items{get;set;}=[];}
class Item{public int Id{get;set;}public int OrderId{get;set;}public Order? Order{get;set;}public int ProductId{get;set;}public Product? Product{get;set;}public string ProductName{get;set;}="";public int Quantity{get;set;}public decimal UnitPrice{get;set;}}
record Reg(string FullName,string StudentId,string Email,string Password);record Login(string? Email,string? Password);record Prod(string Name,int CategoryId,decimal Price,int StockQuantity,string? Emoji,bool IsActive=true);record CatReq(string? Name);record NewOrder(List<NewItem>? Items,string PickupOption,string PaymentMethod,string? Notes);record NewItem(int ProductId,int Quantity);record StatusUpdate(string Status);record Profile(string FullName,string? Phone);
